+<?php
+declare(strict_types=1);
+
+namespace App\Cart;
+
+final class PromoCodeApplier
+{
+    private const DISCOUNT = 0.10;
+
+    public function apply(array $cart, ?string $promoCode, PromoCodeRepository $repo): array
+    {
+        if ($promoCode === null) {
+            return $cart;
+        }
+
+        if (count($cart['items']) <= 3) {
+            return $cart;
+        }
+
+        $promo = $repo->findByCode($promoCode);
+        if ($promo === null) {
+            return $cart;
+        }
+
+        $total = 0.0;
+        foreach ($cart['items'] as $item) {
+            $total += $item['price'] * $item['qty'];
+        }
+
+        $cart['total'] = $total * (1 - self::DISCOUNT);
+
+        return $cart;
+    }
+}

